for i = 1 to n−1:
  for j = n downto i+1:
    if A[j] < A[j−1]: swap(A[j], A[j−1])

for i = 1 to n − 1:
  for j = n downto i + 1:
    if A[j] < A[j−1]: swap(A[j], A[j−1])

for j = 2 to n:
  key = A[j]; i = j − 1
  while i ≥ 1 and A[i] > key:
    A[i+1] = A[i]; i = i − 1
  A[i+1] = key
